class Node {
	constructor(mySnake, x, y, r, nextnode) {
		this.mySnake = mySnake;
		this.state = 0; // 0= moving, 1= mouse tracking
		this.pos = createVector(x, y);
		this.r = r;
		this.nextnode = nextnode
		if (nextnode) {
			this.heading = p5.Vector.sub(nextnode.pos, this.pos).normalize();
		} else {
			this.heading = p5.Vector.random2D();
		}
		this.pos_r = this.heading.copy().rotate(HALF_PI).mult(this.r).add(this.pos);
		this.pos_l = this.heading.copy().rotate(-HALF_PI).mult(this.r).add(this.pos);
	}

	constrainPos() {
		if (!this.nextnode) {
			let m;
			if (this.state == 1) { //aim at mouse
				m = this.pos.dist(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
				if (m < 10) return;
			} else { // otherwise fixed speed
				m = this.r * 0.1*ticks/20;
			}
			let step = this.heading.copy();
			this.heading.mult(min(m, this.r) * 0.9);
			this.pos.add(this.heading);
			this.heading.normalize();

		} else {
			let dir = p5.Vector.sub(this.pos, this.nextnode.pos);
			dir.normalize();
			dir.mult(this.mySnake.spacing);
			dir.add(this.nextnode.pos);
			this.pos = dir;
		}
	}

	constrainHeading() {
		if (!this.nextnode) {
			if (this.state == 1) { // aim at mouse
				let target = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
				target.sub(this.pos);
				target.normalize();
				this.heading = target;
			} else { //oscilate direction
				let amplitude = 0.05;
				let period = this.mySnake.rate;
				let triwave = (4 * amplitude / period) * abs(((millis() / 1000 - 1.0) % period) - period / 2) - amplitude;
				this.heading.rotate(triwave);
			}
			return;
		}

		this.heading = p5.Vector.sub(this.nextnode.pos, this.pos).normalize();

		if (!this.nextnode.heading) return;

		let maxangle = PI * 0.2;
		if (abs(this.heading.angleBetween(this.nextnode.heading)) < maxangle) return;

		let dir = p5.Vector.sub(this.pos, this.nextnode.pos);
		let rotAngle = constrain(this.heading.angleBetween(this.nextnode.heading), -maxangle, maxangle);
		dir.rotate(rotAngle);
		dir.add(this.nextnode.pos);
		this.pos = dir;
	}

	update(s) {
		this.state = s;
		this.constrainHeading();
		this.constrainPos();
		this.pos_r = this.heading.copy().rotate(HALF_PI).mult(this.r).add(this.pos);
		this.pos_l = this.heading.copy().rotate(-HALF_PI).mult(this.r).add(this.pos);
	}

	show() {
		push();
		noFill();
		stroke(255);
		strokeWeight(2)
		circle(this.pos.x, this.pos.y, this.r * 2);
		circle(this.pos.x, this.pos.y, min(5, this.r * 2));
		if (this.nextnode) line(this.pos.x, this.pos.y, this.nextnode.pos.x, this.nextnode.pos.y);
		stroke("red");
		circle(this.pos_r.x, this.pos_r.y, min(5, this.r * 2));
		stroke("green");
		circle(this.pos_l.x, this.pos_l.y, min(5, this.r * 2));
		pop();
	}
}

