class Snake {
	constructor(x, y, r, sizearray, spacing, c) {
		this.rate = random(4, 6);
		this.state = 0; // 0= moving, 1= mouse tracking
		this.spacing = spacing * scalefactor;
		this.body = [];
		this.body.push(new Node(this, x, y, r * scalefactor)); // nose is body[0]
		this.c1 = c;
		this.c2 = lerpColor(c, color("black"), 0.5);

		for (let i = 1; i < sizearray.length; i++) {
			this.add(sizearray[i] * scalefactor, spacing * scalefactor);
		}
	}

	add(r, d) {
		let nextnode = this.body[this.body.length - 1];
		let nextpos = p5.Vector.add(nextnode.pos, p5.Vector.random2D().mult(d));
		this.body.push(new Node(this, nextpos.x, nextpos.y, r, nextnode));
	}

	update() {
		for (let i = 0; i < this.body.length; i++) {
			let n = this.body[i];
			n.update(this.state);
		}

		let r = this.body[0].r * 1.5;
		if (this.body[0].pos.x <= r || this.body[0].pos.x >= width - r || this.body[0].pos.y <= r || this.body[0].pos.y >= height - r) { // constrain to screen
			let target = createVector(width / 2, height / 2);
			target.sub(this.body[0].pos);
			target.normalize();
			target.rotate(random(-0.5, 0.5)); // stop loops
			this.body[0].heading = target;
		}
	}

	shapes() {
		let nose = this.body[0].heading.copy().mult(this.body[0].r).add(this.body[0].pos);
		let nose_r = this.body[0].heading.copy().mult(this.body[0].r).rotate(HALF_PI / 2).add(this.body[0].pos);
		let nose_l = this.body[0].heading.copy().mult(this.body[0].r).rotate(-HALF_PI / 2).add(this.body[0].pos);
		beginShape();
		curveVertex(this.body[0].pos_l.x, this.body[0].pos_l.y)
		curveVertex(nose_l.x, nose_l.y)
		curveVertex(nose.x, nose.y)
		curveVertex(nose_r.x, nose_r.y)
		for (let i = 0; i < this.body.length; i++) {
			curveVertex(this.body[i].pos_r.x, this.body[i].pos_r.y);
		}
		for (let i = this.body.length - 1; i >= 0; i--) {
			curveVertex(this.body[i].pos_l.x, this.body[i].pos_l.y);
		}
		curveVertex(nose_l.x, nose_l.y)
		curveVertex(nose.x, nose.y)
		curveVertex(nose_r.x, nose_r.y)
		curveVertex(this.body[0].pos_r.x, this.body[0].pos_r.y)
		endShape();

		for (let i = this.body.length - 1; i >= 0; i--) {
			fill(lerpColor(this.c1,this.c2,i%2));
			circle(this.body[i].pos.x, this.body[i].pos.y, 2 * this.body[i].r);
		}

		//tongue
		if(random()<0.005) {
			push()
			noFill();
			stroke("darkred");
			strokeWeight(8*scalefactor);
			let tt=this.body[0].heading.copy().mult(this.body[0].r*2.5).add(this.body[0].pos);
			let t1=this.body[0].heading.copy().rotate(PI/6).mult(this.body[0].r*0.5).add(tt);
			let t2=this.body[0].heading.copy().rotate(-PI/6).mult(this.body[0].r*0.5).add(tt);
			line(nose.x, nose.y, tt.x,tt.y);
			strokeWeight(4*scalefactor);
			line(t1.x, t1.y, tt.x,tt.y);
			line(t2.x, t2.y, tt.x,tt.y);
			pop();
		}

		noStroke();
		circle(this.body[1].pos.x, this.body[1].pos.y, 2 * this.body[1].r - 8 * scalefactor); // overdraw head;

		//eyes
		fill("black");
		let e1=this.body[1].heading.copy().rotate(PI/3).mult(this.body[1].r*0.7).add(this.body[1].pos);
		let e2=this.body[1].heading.copy().rotate(-PI/3).mult(this.body[1].r*0.7).add(this.body[1].pos);
		circle(e1.x,e1.y,20 * scalefactor);
		circle(e2.x,e2.y,20 * scalefactor);

	}

	show() {

		stroke("black");

		if (!debug) {
			strokeWeight(6 * scalefactor);
			fill(this.c1);
			this.shapes();
		} else {
			for (let n of this.body) {
				n.show();
			}
		}
	}

	inMouseRange() {
		let l = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), this.body[0].pos.x, this.body[0].pos.y);
		return (l < 2 * this.body[0].r);
	}
}

