const target_size = 1500


const limitFrameRate = true; // if true, spawn and destroy snakes to keep the framerate between 15 and 30 FPS,
                             // if false, spawn 6 regardles of system performance
let debug = false;
let grabbing = -1;
let scalefactor = 1;
let lastmillis;
let ticks;
let fr;

let aSnake = [];
let sizes = [40, 65, 50, 48, 47, 46, 44, 43, 42, 41, 40, 39, 37, 36, 35, 34, 33, 32, 31, 30, 28, 27, 26, 25, 24, 23, 21, 20, 19, 18, 17, 15, 14, 12, 11, 7];
let colors = ["cyan", "yellow", "violet"];
let spacing = 40;

function setup() {
	lastmillis = millis();
	pixelDensity(1);
	createCanvas(windowWidth, windowHeight);

	scalefactor = max(width, height) / target_size;

	background(100);

	for (let i=0; i<(limitFrameRate?1:6); i++) {
	  aSnake.push(new Snake(width / 2, height / 2, sizes[0], sizes, spacing, color(colors[i%colors.length])));
	}

	strokeWeight(5);
	stroke(0);
	fill(255);
	fr = frameRate();
}

function draw() {
	ticks = millis() - lastmillis;
	lastmillis = millis();

	if (!debug) {
		background(100, 100, 100, 50);
	} else {
		background(100, 100, 100);
	}

	if (!((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
		grabbing = -1;
	}
	for (let i = 0; i < aSnake.length; i++) {
		if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && grabbing == -1 && aSnake[i].inMouseRange()) {
			grabbing = i;
		}

		if (grabbing == i) {
			aSnake[i].state = 1;
		} else {
			aSnake[i].state = 0;
		}
		aSnake[i].update();
		aSnake[i].show();
	}

	if (limitFrameRate) {
		fr = 0.9 * fr + 0.1 * frameRate();
		if (frameRate() > 30) aSnake.push(new Snake(width / 2, height / 2, sizes[0], sizes, spacing, color(random(colors))));
		if (frameRate() < 15) aSnake.pop();
	}
}

